Subroutine Suspendable Query(name As String, stock As Integer) As Result<Integer, String>
  If stock = 0 Then
    Return Failure(name + " has no stock");
  EndIf
  Return Success(stock);
EndSubroutine

Algorithm Order
  Define north As Integer;
  Define south As Integer;
  Define west As Integer;
  Read north;
  Read south;
  Read west;
  Tasks outcome
    Spawn Query("North", north);
    Spawn Query("South", south);
    Spawn Query("West", west);
  EndTasks
  Switch outcome Do
    Some(report): Write "Order suspended: ", report.first;
    None: Write "Order confirmed: ", north + south + west;
  EndSwitch
EndAlgorithm

